"""Public, local-only product demonstrations, derived from reviewed game assets."""
from html import escape as e
from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[1]
SIZES=json.loads((ROOT/'catalog/games-image-sizes.json').read_text())

def image(src,alt,classes='',eager=False):
    width,height=SIZES[src]
    return f'<img src="../{e(src)}" alt="{e(alt)}" class="{classes}" loading="{"eager" if eager else "lazy"}" fetchpriority="{"high" if eager else "auto"}" decoding="async" width="{width}" height="{height}">'

def gallery(data):
    return '<div class="game-gallery">'+''.join('<figure>'+image(i['src'],i['alt'])+'<figcaption>'+e(i.get('caption',i['alt']))+'</figcaption></figure>' for i in data.get('screenshots',[]))+'</div>'

def render_game(kind):
    data=json.loads((ROOT/'catalog/games-media.json').read_text())[kind]
    if kind=='echo':
        portals=''.join(f'<button type="button" class="realm-portal realm-{i}" data-realm="{e(w["id"])}" data-description="{e(w["description"])}" aria-pressed="{"true" if i==0 else "false"}">{image(w["image"],"",eager=i==0)}<span><strong>{e(w["name"])}</strong><small>100 poziomów kampanii</small></span></button>' for i,w in enumerate(data['worlds']))
        w=data['worlds'][0]
        content=f'''<section class="game-intro shell"><p class="eyebrow">ProgressKit / gry / 0.10.0 Alpha</p><h1>ECHO<br><em>WORLDS</em></h1><p class="game-lead">Jedno połączenie.<br>Sześć krain do odkrycia.</p><p>Przygoda match-3 z kampanią fantasy: 600 poziomów w 60 lokacjach. Wersja Alpha, w rozwoju.</p><a class="world-control world-control--primary" href="#krainy">Odkryj krainy</a><a class="game-text-link" href="#mechanika">Spróbuj połączenia</a></section>
        <section class="shell" id="krainy"><p class="eyebrow">Wybierz swoją podróż</p><h2>Po drugiej stronie portalu.</h2><p>Wybierz krainę, aby obejrzeć prawdziwą planszę z aplikacji. Portale są prezentacją przestrzenną.</p><div class="realm-portals">{portals}</div><div class="realm-detail"><canvas class="game-canvas" data-game-scene="echo" aria-hidden="true"></canvas><div><p class="eyebrow">Wybrana kraina</p><h3 data-realm-title>{e(w['name'])}</h3><p data-realm-description>{e(w['description'])}</p><p class="game-provenance">Autentyczny ekran rozgrywki z repozytorium gry.</p></div><figure>{image(w['image'],w['name']+' — plansza match-3','realm-board',True)}</figure></div></section>
        <section class="shell game-demo" id="mechanika"><div><p class="eyebrow">Demonstracja w przeglądarce</p><h2>Połącz. Uwolnij echo.</h2><p>Zamień dwa sąsiednie symbole. Trzy jednakowe tworzą połączenie i uruchamiają kaskadę.</p><p>To niezależna demonstracja zasady match-3. Kampania, boostery i zapisy pozostają w aplikacji.</p><p role="status" data-match-status>Wybierz symbol, a potem jego sąsiada.</p><button class="world-control" type="button" data-match-reset>Nowa plansza</button></div><div class="match-board" role="group" aria-label="Demonstracyjna plansza match-3"></div></section>'''
        title='ECHO WORLDS';sub='Sześć krain. Jedna podróż.'
    else:
        species=''.join(f'<button type="button" data-species="{e(s["id"])}" data-portrait="../{e(s.get("portrait",s["image"]))}" data-description="{e(s["description"])}" aria-pressed="{"true" if i==0 else "false"}">{image(s.get("thumbnail",s["image"]),"",eager=False)}<span>{e(s["name"])}</span></button>' for i,s in enumerate(data['species']))
        furniture=''.join(f'<button type="button" data-furniture="{e(f["id"])}" aria-pressed="false">{image(f["image"],"")}<span>{e(f["name"])}</span></button>' for f in data.get('furniture',[]))
        s=data['species'][0]
        content=f'''<section class="game-intro shell"><p class="eyebrow">ProgressKit / Android / w testach</p><h1>Małe zadania.<br><em>Żywy świat.</em></h1><p class="game-lead">Twój dzień ma<br>nowego towarzysza.</p><p>TaskPet łączy organizer zadań, wirtualnego pupila i urządzanie pokoju. Publiczna wersja jest w przygotowaniu.</p><a class="world-control world-control--primary" href="#pokoj">Poznaj pupila</a><a class="game-text-link" href="#zadanie">Zobacz, jak to działa</a></section>
        <section class="shell" id="pokoj"><p class="eyebrow">Dark Violet Crystal Glass</p><h2>Miejsce, do którego chcesz wracać.</h2><p>Wybierz pupila i wyposażenie. Obróć pokój przyciskami lub przeciągnij go poziomo. Dotknij zwierzaka, by zobaczyć jego reakcję.</p><div class="taskpet-room"><canvas class="game-canvas" data-game-scene="taskpet" aria-hidden="true"></canvas><div class="room-fallback" aria-hidden="true"><i></i><i></i></div><button type="button" class="pet-interaction" aria-label="Pogłaszcz pupila">{image(s.get('portrait',s['image']),s['name'],'living-pet',True)}<span aria-hidden="true" class="pet-joy">♥</span></button><div class="room-controls"><button type="button" class="world-control" data-room-turn="-1" aria-label="Obrót w lewo — pokój">Obrót w lewo</button><button type="button" class="world-control" data-room-turn="1" aria-label="Obrót w prawo — pokój">Obrót w prawo</button><button type="button" class="world-control" data-room-view>Blisko / daleko</button></div></div><p role="status" data-pet-status>{e(s['name'])}: {e(s['description'])}</p><div class="species-picker" aria-label="Wybór pupila">{species}</div><p class="game-provenance">Pokój jest sceną 3D. Pupil jest animowaną prezentacją 2.5D oryginalnej grafiki z aplikacji. Pokaz działa w pamięci przeglądarki.</p><h3>Twój pokój, Twoje tempo.</h3><p>Wybierz mebel, aby ustawić go w pokazowym pokoju. Prezentacja nie kupuje ani nie odblokowuje przedmiotów w aplikacji.</p><div class="furniture-picker">{furniture}</div><p role="status" data-furniture-status>Wybierz wyposażenie.</p></section>
        <section class="shell game-demo" id="zadanie"><div><p class="eyebrow">Organizer + chowaniec</p><h2>Zrób miejsce<br>na małe zwycięstwa.</h2><p>W aplikacji: zadania jednorazowe, codzienne, tygodniowe i dwutygodniowe, godziny, przypomnienia oraz widżety Android.</p><p>Ukończenie zadania daje nagrodę i wspiera rozwój pupila. Poniższy pokaz korzysta z przykładowego zadania, bez dostępu do zapisów aplikacji.</p></div><div class="task-demo"><p class="eyebrow">Przykładowy dzień</p><h3>Chwila na spacer</h3><p>Dzisiaj · 17:00 · codziennie</p><button type="button" class="world-control world-control--primary" data-task-complete>Ukończ zadanie</button><progress aria-label="Rozwój pupila w pokazie" max="100" value="20"></progress><p role="status" data-task-status>20 / 100 XP w pokazie</p><button type="button" class="world-control" data-task-reset>Zacznij pokaz od nowa</button></div></section>
        <section class="shell"><p class="eyebrow">Przedmioty i personalizacja</p><h2>Rozwijaj swój mały świat.</h2><p>Meble, dekoracje, zapasy i dodatki są częścią systemu przedmiotów TaskPet. Ta prezentacja nie jest sklepem i nie obsługuje płatności. Dostępność zakupów Google Play nie została potwierdzona.</p></section>'''
        title='TaskPet';sub='Małe zadania. Żywy świat.'
    hero='<div class="game-hero-art">'+image(data['hero'],title+' — oryginalna grafika prezentacyjna',eager=True)+(image(data['species'][0].get('portrait',data['species'][0]['image']),'','hero-pet',True) if kind=='taskpet' else '')+'</div>'
    content=content.replace('</section>',hero+'</section>',1)
    if kind=='echo':
        content+='<section class="shell"><p class="eyebrow">Przeszkody i pomocnicy</p><h2>Każde połączenie ma znaczenie.</h2><div class="game-items">'+''.join('<figure>'+image(item['image'],item['name'])+'<figcaption>'+e(item['name'])+'</figcaption></figure>' for item in data.get('boosters',[])+data.get('obstacles',[]))+'</div><p class="game-provenance">Oryginalne ikony boosterów i fragment rzeczywistej planszy z przeszkodami.</p></section>'
    else:
        room_choices='<div class="room-picker">'+''.join('<button class="world-control" type="button" data-room-variant="'+e(item['id'])+'" data-room-image="../'+e(item['image'])+'" aria-pressed="'+('true' if i==0 else 'false')+'">'+e(item['name'])+'</button>' for i,item in enumerate(data['rooms']))+'</div>'
        content=content.replace('<h3>Twój pokój, Twoje tempo.</h3>',room_choices+'<h3>Twój pokój, Twoje tempo.</h3>')
    content+=f'<section class="shell"><p class="eyebrow">Z istniejącej aplikacji</p><h2>Zobacz prawdziwe ekrany.</h2>{gallery(data)}</section>'
    video=data.get('video')
    if video:content+=f'<section class="shell"><h2>{e(title)} w ruchu</h2><video controls playsinline preload="none" poster="../{e(data.get("hero",data["screenshots"][0]["src"]))}" width="1280" height="720"><source src="../{e(video)}" type="video/mp4"></video><p class="game-provenance">Materiał prezentacyjny z oryginalnych zasobów i ekranów aplikacji.</p></section>'
    content+=f'<section class="shell game-close"><p class="eyebrow">{e(title)} / w rozwoju</p><h2>{e(sub)}</h2><p>Publiczna dystrybucja jest w przygotowaniu. Nie udostępniamy tutaj prywatnych kompilacji.</p><a class="world-control" href="mailto:pawel@progresskit.pl">Napisz do ProgressKit</a><a class="game-text-link" href="../projekty/">Wszystkie projekty</a></section>'
    return '<div class="game-experience game-'+kind+'" data-game="'+kind+'">'+content+'</div>'
